const WA_LIMIT = 3800; // margen seguro bajo el límite real de 4096

const rows = $input.all().map(r => r.json);
const categoria = ($('When Executed by Another Workflow').first().json.categoria || '').trim();

// Si el nodo DB falló
if (!rows || rows.length === 0 || rows[0].error) {
  return [{ json: {
    respuesta_agente: 'En este momento no puedo consultar el menú. Intenta en unos segundos o dime qué quieres pedir.',
    total_items: 0
  }}];
}

const ABREV = {
  'personal': 'P.', 'personal (25 cm)': 'P. 25cm',
  'mediana': 'M.', 'mediana (32 cm)': 'M. 32cm',
  'familiar': 'F.', 'familiar (45 cm)': 'F. 45cm',
  'única': 'Única', 'unica': 'Única',
  'pequena': 'Peq.', 'pequeña': 'Peq.', 'pequeño': 'Peq.',
  'grande': 'G.', 'extra grande': 'XL', 'xl': 'XL',
  'small': 'S.', 'estándar': 'Std.', 'estandar': 'Std.',
  'individual': 'Ind.',
  'ración': 'Rac.', 'racion': 'Rac.',
  'ración individual': 'Rac. Ind.', 'racion individual': 'Rac. Ind.',
  'ración grande': 'Rac. G.', 'racion grande': 'Rac. G.',
  'ración grande (14 uds)': 'Rac. G. 14u', 'racion grande (14 uds)': 'Rac. G. 14u',
  'ración (6 uds)': 'Rac. 6u', 'racion (6 uds)': 'Rac. 6u',
  'ración (8 uds)': 'Rac. 8u', 'racion (8 uds)': 'Rac. 8u',
  'lata 330 ml': 'Lata', 'botella 500 ml': '500ml',
  'botella 1.5 l': '1,5L', 'botella 1,5 l': '1,5L',
};

function abreviar(nombre) {
  return ABREV[nombre.trim().toLowerCase()] || nombre;
}

// Agrupar por categoría
const cats = {};
for (const row of rows) {
  const cat = row.category_name || 'Otros';
  if (!cats[cat]) cats[cat] = {};
  const item = row.item_name;
  if (!cats[cat][item]) cats[cat][item] = { available: row.is_active !== false, variants: [] };
  if (row.variant_name && row.price != null) {
    cats[cat][item].variants.push({ name: row.variant_name, price: row.price });
  }
}

const catNames = Object.keys(cats);
const totalItems = Object.values(cats).reduce((acc, items) => acc + Object.keys(items).length, 0);

if (catNames.length === 0) {
  const msg = categoria
    ? `No encontré productos en la categoría "${categoria}".`
    : 'No hay productos disponibles en este momento.';
  return [{ json: { respuesta_agente: msg, total_items: 0 } }];
}

// Construir bloque de texto para una categoría
function buildCatBlock(catName) {
  const items = cats[catName];
  const lines = [`*${catName}*`];
  for (const [itemName, data] of Object.entries(items)) {
    const avail = data.available ? '' : ' _(no disp.)_';
    if (data.variants.length === 0) {
      lines.push(`- ${itemName}${avail}`);
    } else {
      const vStr = data.variants
        .map(v => `${abreviar(v.name)} €${Number(v.price).toFixed(2).replace('.', ',')}`)
        .join(' / ');
      lines.push(`- ${itemName}: ${vStr}${avail}`);
    }
  }
  return lines.join('\n');
}

// Si se pidió categoría específica, devolver solo esa
if (categoria) {
  const blocks = catNames.map(buildCatBlock).join('\n\n');
  const truncated = blocks.length > WA_LIMIT
    ? blocks.slice(0, WA_LIMIT) + '\n_(lista recortada por longitud)_'
    : blocks;
  return [{ json: { respuesta_agente: truncated, total_items: totalItems } }];
}

// Sin categoría: intentar devolver todo el menú
const fullBlocks = catNames.map(buildCatBlock).join('\n\n');

if (fullBlocks.length <= WA_LIMIT) {
  // Cabe completo
  return [{ json: { respuesta_agente: fullBlocks, total_items: totalItems } }];
}

// No cabe completo → devolver lista de categorías y pedir que elija
const catList = catNames.map(c => `• ${c}`).join('\n');
const respuesta =
  `Tenemos las siguientes categorías:\n\n${catList}\n\n` +
  `¿Sobre cuál quieres ver los productos y precios?`;

return [{ json: { respuesta_agente: respuesta, total_items: totalItems, modo: 'categorias' } }];
